const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
async function until(fn,label){const end=performance.now()+10000;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
const click=s=>{assert($(s),'Missing '+s);$(s).click();},field=(s,v)=>{$(s).value=String(v);$(s).dispatchEvent(new Event('change',{bubbles:true}));};
const input={id:'controls-input',name:'Synthetic factory controls',state:'connected',type:'input',onmidimessage:null};
Object.defineProperty(navigator,'requestMIDIAccess',{configurable:true,value:async()=>({inputs:new Map([[input.id,input]]),onstatechange:null})});
const packet=(channel,number,value=127,type='Note',at=performance.now())=>input.onmidimessage?.({data:new Uint8Array([(type==='CC'?0xb0:0x90)+channel-1,number,value]),timeStamp:at});
async function tap(channel,note,at){packet(channel,note,127,'Note',at);await sleep(25);packet(channel,note,0,'Note',at===undefined?undefined:at+20);await sleep(20);}
async function cc(channel,number,value){packet(channel,number,value>>7,'CC');packet(channel,number+32,value&127,'CC');await sleep(45);}
