async function importProfile(file){const text=await(await fetch('/api/controller-fixtures/'+file)).text(),dt=new DataTransfer();dt.items.add(new File([text],file,{type:'application/json'}));$('#catalog-file').files=dt.files;$('#catalog-file').dispatchEvent(new Event('change',{bubbles:true}));await until(()=>$('#catalog-status').textContent.startsWith('Imported '),'Import');assert($('#catalog-status').textContent.includes('0 file(s) rejected'),$('#catalog-status').textContent);field('#catalog-profile',id);}
async function apply(){field('#catalog-profile',id);field('#catalog-device',input.id);click('#catalog-apply');await until(()=>$('#catalog-profile')?.options.length===2,'Editor restored');}
