 const {state,engine}=app,d=state.decks[0],report={startedAt:new Date().toISOString(),scope:'Actual browser app, recovered factory profiles, synthetic MIDI/authored tones; no hardware/native/vendor sonic acceptance',checks:[],errors:[],audio:[],fullParity:false,physicalCompatibilityVerified:false},witnesses=[];$('#controls-run').disabled=true;
