  const old=JSON.stringify(state.mappings);await importProfile('factory-002.json');assert($('#catalog-profile-detail').textContent.includes('356 translated assignments'),'v3 profile');await apply();await until(()=>state.mappings.length===356,'v3 companion upgrade');assert(JSON.stringify(state.mappings.slice(0,335))===old,'Earlier assignments replaced');
  report.checks.push('Actual v2→v3 import/bind retained335 assignments and added21, including a companion fader-enable action at its existing modifier address');
