  state.settings['Cue Mix']=0;state.settings['Cue Volume']=10;state.settings['Master Cue']=false;state.settings['Split Cue']=false;engine.setMonitorSettings({mix:0,volume:.1,masterCue:false,splitCue:false});engine.setPFL(0,true);d.pfl=true;
  Object.assign(d,{position:0,rate:1,keylock:false,keyShift:0,loop:false,reverse:false,quantize:false,slip:false,stemSlip:'off',sync:false,mode:'INT'});Object.assign(d.track,{duration:12,bpm:120,grid:0,gridWarpMarkers:[],gridMarkers:[],analyzed:true});
  const sr=engine.ctx.sampleRate,buffer=engine.ctx.createBuffer(2,sr*12,sr);for(let c=0;c<2;c++)for(let n=0;n<buffer.length;n++)buffer.getChannelData(c)[n]=.1*Math.sin(2*Math.PI*(c?5500:5000)*n/sr);engine.buffers.set(d.track.id,buffer);engine.stemBuffers.delete(d.track.id);engine.clearDeckScratchCache(0);engine.mix(0,'level',.8);
