  async function measure(label){await sleep(90);const data=await Promise.all(witnesses.map((node,i)=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM timeout')),3000);node.port.onmessage=({data})=>{if(data.type==='done'){clearTimeout(timer);let sum=0,max=0;for(const v of data.data){assert(Number.isFinite(v),'Nonfinite PCM');sum+=v*v;max=Math.max(max,Math.abs(v));}resolve({bus:i?'cue':'master',rms:Math.sqrt(sum/data.data.length),peak:max,frames:data.data.length});}};node.port.postMessage({type:'capture',id:label,frames:Math.round(sr*.12)});})));const result={label,buses:data};report.audio.push(result);return data;}
  await cc(1,3,16383);await tap(2,7);await until(()=>d.playing,'Play');step('Measuring master and cue controls…');const baseline=await measure('baseline');
  await cc(1,3,0);assert(engine.masterVolume===0&&$('#master-level-value').textContent.includes('0%'),'Master zero not visible');const masterMute=await measure('master-zero');assert(masterMute[0].rms<baseline[0].rms*.005,'Master zero did not mute actual master audio');assert(masterMute[1].rms>baseline[1].rms*.9,'Master volume muted independent PFL cue');
  await cc(1,3,16383);await cc(1,4,0);const cueMute=await measure('cue-zero');assert(cueMute[1].rms<baseline[1].rms*.005,'Cue zero did not mute actual headphone bus');assert(cueMute[0].rms>baseline[0].rms*.9,'Cue volume changed master bus');await cc(1,4,1638);report.checks.push('Actual PCM proves master0 mutes master while PFL remains audible, and cue0 mutes cue while master remains audible');
  step('Measuring first-slot FX depth…');await cc(2,6,0);await tap(2,0);assert(state.fx[0][0].on,'FX On did not address first slot');const fxOpen=await measure('lpf-depth-zero');await cc(2,6,16383);const fxCut=await measure('lpf-depth-full');assert(fxCut[0].rms<fxOpen[0].rms*.1,'Slot Depth did not affect real LPF output');assert(state.fx[0][1].depth===17&&state.fx[0][2].depth===83&&state.fx[1][0].depth===42,'Depth changed another slot/unit');await tap(2,0);report.checks.push('Source first-slot enable/depth changed actual LPF audio and preserved other slot/unit depths');
  const baseBeat=state.fx[0][0].beat;await cc(2,7,16383);assert(state.fxBeatMultipliers[0]===8&&state.fxBeatMultipliers[1]===1,'Beat multiplier unit');assert(state.fx[0][0].beat===baseBeat&&engine.fxState[0][0][0].beat===Number(baseBeat.split('/')[0])/Number(baseBeat.split('/')[1]||1)*8,'Multiplier lost base beat or did not reach active FX configuration');report.checks.push('Unit beat multiplier reached active effect configuration without changing slot base beats');
  step('Checking deferred FX selection and user override…');const before=state.fx[0][0].name;await cc(5,6,16383);assert(state.fx[0][0].name===before,'Open FX list committed prematurely');assert($('[data-fx-select="0:0"]').size===6,'Pending selection not visible');await until(()=>state.fx[0][0].name!==before,'Deferred FX selection');await cc(5,6,0);field('[data-fx-select="0:0"]','Reverb');await sleep(2100);assert(state.fx[0][0].name==='Reverb','Pending controller timer overwrote manual selection');report.checks.push('Open FX selection deferred commit, displayed pending choice, and respected a later manual selection');
  step('Checking source transport/fader/library actions…');await tap(2,7);await until(()=>!d.playing,'Pause');d.cue=1;d.position=3;await tap(5,7);await until(()=>d.playing,'Stutter start');assert(engine.position(d)<1.6,'Stutter did not restart temp cue');await tap(2,7);await until(()=>!d.playing,'Pause stutter');
  const at=performance.now();await tap(5,12,at);await tap(5,12,at+500);await tap(5,12,at+1000);assert(Math.abs(d.track.bpm-120)<.1,'Source Tap Tempo');
  await cc(2,0,0);packet(2,4);await sleep(20);await cc(2,0,8192);await until(()=>d.playing,'Enabled fader start');await cc(2,0,0);await until(()=>!d.playing,'Fader back cue');packet(2,4,0);await sleep(20);await cc(2,0,8192);assert(!d.playing,'Fader start stayed enabled after Shift release');
